draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

var wx = W * 0.16;
var yTop = H * 0.10, yBot = H * 0.92;

// the long straight wire
ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(wx, yTop); ctx.lineTo(wx, yBot);
ctx.stroke();
// current arrow up the wire
ctx.beginPath();
ctx.moveTo(wx, yTop + 26); ctx.lineTo(wx - 5, yTop + 36);
ctx.moveTo(wx, yTop + 26); ctx.lineTo(wx + 5, yTop + 36);
ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("I, rising", wx - 14, yTop - 2);

// field crosses to the right of the wire, thinning with distance
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
var i, j;
for (i = 0; i < 7; i++) {
  var fx = wx + (W * 0.78) * Math.pow((i + 0.6) / 7, 1.5);
  var sz = 6.5 / (1 + 3.2 * (fx - wx) / W);
  for (j = 0; j < 4; j++) {
    var fy = yTop + (yBot - yTop) * (j + 0.5) / 4;
    ctx.beginPath();
    ctx.moveTo(fx - sz, fy - sz); ctx.lineTo(fx + sz, fy + sz);
    ctx.moveTo(fx - sz, fy + sz); ctx.lineTo(fx + sz, fy - sz);
    ctx.stroke();
  }
}

// the loop
var x1 = W * 0.40, x2 = W * 0.82;
var ly1 = H * 0.24, ly2 = H * 0.78;
ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
ctx.strokeRect(x1, ly1, x2 - x1, ly2 - ly1);

// the thin strip dr
var sx = W * 0.56, sw = W * 0.045;
ctx.fillStyle = C.figure;
ctx.globalAlpha = 0.35;
ctx.fillRect(sx, ly1, sw, ly2 - ly1);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
ctx.strokeRect(sx, ly1, sw, ly2 - ly1);
ctx.fillStyle = C.figure;
ctx.fillText("dr", sx + sw + 3, ly1 - 5);

// distance markers
ctx.strokeStyle = C.figure;
ctx.setLineDash([3, 3]);
ctx.beginPath();
ctx.moveTo(wx, ly2 + 16); ctx.lineTo(x1, ly2 + 16);
ctx.moveTo(wx, ly2 + 34); ctx.lineTo(x2, ly2 + 34);
ctx.moveTo(wx, ly1 - 18); ctx.lineTo(sx, ly1 - 18);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.figure;
ctx.fillText("a", (wx + x1) / 2 - 3, ly2 + 13);
ctx.fillText("b", (wx + x2) / 2 - 3, ly2 + 31);
ctx.fillText("r", (wx + sx) / 2 - 3, ly1 - 21);

// loop height label
ctx.fillStyle = C.ink;
ctx.fillText("L", x2 + 6, (ly1 + ly2) / 2);
ctx.fillText("B = mu0 I / 2 pi r, into the page", W * 0.30, H * 0.13);
ctx.fillStyle = C.accent;
ctx.fillText("strip area = L dr", sx - 18, ly2 + 52);
